async function loadCatalogue(request) {
  let response;
  try {
    response = await request("/products.json");
  } catch {
    return { error: "تعذر الاتصال بالخادم.", items: [] };
  }
  if (!response.ok) {
    return { error: "خطأ HTTP (" + response.status + ").", items: [] };
  }
  try {
    const body = await response.json();
    if (!Array.isArray(body?.items) || !body.items.every(item =>
      item && typeof item.name === "string" && item.name.trim() !== "" &&
      typeof item.category === "string" && item.category.trim() !== ""
    )) {
      return { error: "بيانات المنتجات غير صالحة.", items: [] };
    }
    return { error: "", items: body.items };
  } catch {
    return { error: "تعذر قراءة JSON.", items: [] };
  }
}

