function maxWindow(items, k) {
  if (k === 0) return 0;
  let current = 0;
  for (let i = 0; i < k; i++) current += items[i];
  let best = current;
  for (let right = k; right < items.length; right++) {
    current += items[right] - items[right - k];
    best = Math.max(best, current);
  }
  return best;
}
