def direct(items, k):
    if k == 0:
        return [0, 0]
    best, reads = None, 0
    for start in range(len(items) - k + 1):
        total = 0
        for i in range(start, start + k):
            total += items[i]
            reads += 1
        if best is None or total > best:
            best = total
    return [best, reads]

def sliding(items, k):
    if k == 0:
        return [0, 0]
    current = 0
    for i in range(k):
        current += items[i]
    best, reads = current, k
    for right in range(k, len(items)):
        current += items[right] - items[right - k]
        reads += 2
        best = max(best, current)
    return [best, reads]

